  },
  speed: {
    type: "number",
    default: 1,
    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["theme","verb","highlight","fly","accent","fontFamily","ink","background","scale","delay","grain","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  verb: "choose",
  highlight: 0,
  fly: 28,
  accent: "#3B5BFD",
  fontFamily: "Instrument Sans",
  scale: 1,
  delay: 0,
  grain: true,
  speed: 1,
};

type DotSortElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof DotSortBase>;

const DotSortInner = forwardRef<
  HTMLDivElement,
  DotSortElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<DotSort>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <DotSortBase
          {...(componentProps as unknown as ComponentProps<typeof DotSortBase>)}
        />
      </div>
    </Sequence>
  );
});

export const DotSort = Interactive.withSchema({
  Component: DotSortInner,
  componentName: "<DotSort>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
